<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { reportApi } from '@/api/business'

const route=useRoute()
const tab=ref(String(route.query.tab||'reports')),loading=ref(false),rows=ref<any[]>([]),templates=ref<any[]>([])
const summary=reactive({drafts:0,reviewing:0,archived:0})
const reportVisible=ref(false),templateVisible=ref(false),templateEditingId=ref<number|null>(null),previewVisible=ref(false),previewContent=ref('')
const previewReportId=ref<number|null>(null),previewTemplateId=ref<number|null>(null),previewTemplateName=ref(''),templatePickerVisible=ref(false),pendingTemplateId=ref<number|null>(null),exportReportVisible=ref(false),exportReportFormat=ref('word')
const form=reactive({reportType:'通用检测报告',customerName:'',templateId:null as number|null,title:'',content:'',version:0})
const template=reactive({code:'',name:'',reportType:'通用检测报告',versionNo:'V1.0',templateContent:'检测报告\n报告编号：{{reportNo}}\n委托单位：{{customerName}}\n检测结论：{{content}}',status:'ENABLED',version:0})

async function load(){loading.value=true;try{Object.assign(summary,await reportApi.summary());[rows.value,templates.value]=await Promise.all([reportApi.list(),reportApi.templates()])}finally{loading.value=false}}
function createReport(){Object.assign(form,{reportType:'通用检测报告',customerName:'',templateId:templates.value[0]?.id??null,title:'',content:'',version:0});reportVisible.value=true}
async function saveReport(){await reportApi.create(form);reportVisible.value=false;ElMessage.success('报告草稿已创建');await load()}
function createTemplate(){templateEditingId.value=null;Object.assign(template,{code:'',name:'',reportType:'通用检测报告',versionNo:'V1.0',templateContent:'检测报告\n报告编号：{{reportNo}}\n委托单位：{{customerName}}\n检测结论：{{content}}',status:'ENABLED',version:0});templateVisible.value=true}
function editTemplate(row:any){templateEditingId.value=row.id;Object.assign(template,{code:row.code,name:row.name,reportType:row.reportType,versionNo:row.versionNo,templateContent:row.templateContent,status:row.status,version:row.version});templateVisible.value=true}
async function saveTemplate(){if(templateEditingId.value)await reportApi.updateTemplate(templateEditingId.value,template);else await reportApi.createTemplate(template);templateVisible.value=false;ElMessage.success(templateEditingId.value?'模板已修改':'模板已创建');await load()}
async function removeTemplate(row:any){try{await ElMessageBox.confirm(`确定删除报告模板“${row.name}”吗？`,'删除报告模板',{type:'warning'});await reportApi.deleteTemplate(row.id);ElMessage.success('报告模板已删除');await load()}catch(error:any){if(error==='cancel'||error==='close')return;ElMessage.error(error?.response?.data?.message||'删除报告模板失败')}}
async function importTemplateFile(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=async()=>{try{const data=await reportApi.importTemplate({fileName:file.name,fileContentBase64:String(reader.result||'')});templateEditingId.value=null;Object.assign(template,{code:`MB${Date.now()}`,name:data.name,reportType:'通用检测报告',versionNo:'V1.0',templateContent:data.templateContent,status:'ENABLED',version:0});templateVisible.value=true}catch(error:any){ElMessage.error(error?.response?.data?.message||'模板导入失败')}finally{input.value=''}};reader.onerror=()=>ElMessage.error('读取模板文件失败');reader.readAsDataURL(file)}
async function exportTemplate(row:any){let format='';try{await ElMessageBox.confirm('请选择模板导出格式','导出模板',{confirmButtonText:'导出 Word',cancelButtonText:'导出 Excel',distinguishCancelAndClose:true,type:'info'});format='word'}catch(action){if(action==='cancel')format='excel';else return}try{const response=await reportApi.exportTemplate(row.id,format);const disposition=String(response.headers['content-disposition']||'');const encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1];const fileName=encoded?decodeURIComponent(encoded):`${row.name}.${format==='word'?'docx':'xlsx'}`;const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download=fileName;link.click();URL.revokeObjectURL(url);ElMessage.success('模板已导出')}catch(error:any){ElMessage.error(error?.response?.data?.message||'模板导出失败')}}
function applyPreview(data:any){previewContent.value=data.content;previewTemplateId.value=data.templateId??null;previewTemplateName.value=data.templateName||''}
async function preview(row:any){previewReportId.value=row.id;applyPreview(await reportApi.preview(row.id));previewVisible.value=true}
async function printReportFromRow(row:any){previewReportId.value=row.id;applyPreview(await reportApi.preview(row.id));if(!previewTemplateId.value){ElMessage.warning('该报告未选择模板，不能打印');return}printReport()}
async function exportReportFromRow(row:any){previewReportId.value=row.id;applyPreview(await reportApi.preview(row.id));if(!previewTemplateId.value){ElMessage.warning('该报告未选择模板，不能导出');return}openReportExport()}
function choosePreviewTemplate(){pendingTemplateId.value=previewTemplateId.value;templatePickerVisible.value=true}
async function confirmPreviewTemplate(){if(previewReportId.value===null)return;try{applyPreview(await reportApi.selectTemplate(previewReportId.value,pendingTemplateId.value));templatePickerVisible.value=false;ElMessage.success('报告模板已更新');await load()}catch(error:any){ElMessage.error(error?.response?.data?.message||'选择模板失败')}}
function openReportExport(){if(!previewTemplateId.value)return;exportReportFormat.value='word';exportReportVisible.value=true}
async function confirmReportExport(){if(previewReportId.value===null||!previewTemplateId.value)return;try{const response=await reportApi.exportReport(previewReportId.value,exportReportFormat.value);const disposition=String(response.headers['content-disposition']||'');const encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1];const extension={word:'docx',excel:'xlsx',pdf:'pdf'}[exportReportFormat.value]||exportReportFormat.value;const fileName=encoded?decodeURIComponent(encoded):`报告.${extension}`;const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download=fileName;link.click();URL.revokeObjectURL(url);exportReportVisible.value=false;ElMessage.success('报告已导出')}catch(error:any){ElMessage.error(error?.response?.data?.message||'报告导出失败')}}
function printReport(){if(!previewTemplateId.value)return;const frame=document.createElement('iframe');frame.style.position='fixed';frame.style.width='0';frame.style.height='0';frame.style.border='0';document.body.appendChild(frame);const safe=previewContent.value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');frame.contentDocument?.write(`<html><head><title>报告打印</title><style>body{padding:32px;font-family:Arial,"Microsoft YaHei",sans-serif}pre{white-space:pre-wrap;line-height:1.9;font-size:14px}</style></head><body><pre>${safe}</pre></body></html>`);frame.contentDocument?.close();setTimeout(()=>{frame.contentWindow?.focus();frame.contentWindow?.print();setTimeout(()=>frame.remove(),1000)},200)}
async function action(row:any,type:string){try{if(type==='submit')await reportApi.submit(row.id);if(type==='review')await reportApi.review(row.id,{approved:true,comment:'审批通过并归档'});if(type==='reject')await reportApi.review(row.id,{approved:false,comment:'退回重新编制'});ElMessage.success(type==='review'?'审批通过，报告已归档':type==='reject'?'报告已退回编制中':'报告已提交审核');await load()}catch(error:any){ElMessage.error(error?.response?.data?.message||'报告状态更新失败');await load()}}
const state=(s:string)=>({DRAFT:'编制中',REVIEWING:'待审核',ARCHIVED:'已归档'} as Record<string,string>)[s]||s
const templateStatus=(s:string)=>s==='ENABLED'?'启用':'停用'
onMounted(load)
</script>

<template>
  <section>
    <div class="page-heading"><div><p>ANALYSIS REPORT</p><h1>分析报告管理</h1></div></div>
    <el-tabs v-model="tab">
      <el-tab-pane label="模板管理" name="templates">
        <div class="report-action-bar"><el-button class="primary-entry" type="primary" @click="createTemplate">新建模板</el-button><label class="import-template-button">导入模板<input type="file" accept=".doc,.docx,.xls,.xlsx" @change="importTemplateFile"/></label></div>
        <div class="content-card">
          <el-table v-loading="loading" :data="templates">
            <el-table-column prop="code" label="模板编码" width="150"/>
            <el-table-column prop="name" label="模板名称"/>
            <el-table-column prop="reportType" label="报告类型"/>
            <el-table-column prop="versionNo" label="版本" width="90"/>
            <el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.status==='ENABLED'?'success':'info'">{{templateStatus(s.row.status)}}</el-tag></template></el-table-column>
            <el-table-column label="操作" width="290" fixed="right"><template #default="s"><div class="report-row-actions"><el-button class="row-action export-template-action" @click="exportTemplate(s.row)">导出</el-button><el-button class="row-action edit-template-action" @click="editTemplate(s.row)">修改</el-button><el-tooltip :content="s.row.deleteDisabledReason||'该模板当前不能删除'" placement="top" :disabled="s.row.deletable"><span class="template-delete-wrapper"><el-button class="row-action delete-template-action" :disabled="!s.row.deletable" @click="removeTemplate(s.row)">删除</el-button></span></el-tooltip></div></template></el-table-column>
          </el-table>
        </div>
      </el-tab-pane>
      <el-tab-pane label="报告管理" name="reports">
        <div class="report-action-bar"><el-button class="primary-entry" type="primary" @click="createReport">新建报告</el-button></div>
        <div class="content-card">
          <el-table v-loading="loading" :data="rows">
            <el-table-column prop="reportNo" label="报告编号" width="170"/><el-table-column prop="customerName" label="委托单位"/><el-table-column prop="reportType" label="报告类型"/><el-table-column prop="title" label="标题"/><el-table-column prop="authorName" label="编制人" width="90"/>
            <el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.status==='ARCHIVED'?'success':s.row.status==='REVIEWING'?'warning':'primary'">{{state(s.row.status)}}</el-tag></template></el-table-column>
            <el-table-column label="操作" width="330" fixed="right"><template #default="s"><div class="report-row-actions"><template v-if="s.row.status==='ARCHIVED'"><el-button class="row-action preview-report-action" @click="preview(s.row)">预览</el-button><el-button class="row-action print-row-action" :disabled="!s.row.templateId" @click="printReportFromRow(s.row)">打印</el-button><el-button class="row-action export-row-action" :disabled="!s.row.templateId" @click="exportReportFromRow(s.row)">导出</el-button></template><el-button v-if="s.row.status==='DRAFT'" class="row-action submit-report-action" @click="action(s.row,'submit')">提交</el-button><template v-if="s.row.status==='REVIEWING'"><el-button class="row-action approve-report-action" @click="action(s.row,'review')">审批通过</el-button><el-button class="row-action reject-report-action" @click="action(s.row,'reject')">退回</el-button></template></div></template></el-table-column>
          </el-table>
        </div>
      </el-tab-pane>
    </el-tabs>
    <el-dialog v-model="reportVisible" title="新建检测报告" width="680px"><el-form label-width="90px"><el-form-item label="报告类型"><el-input v-model="form.reportType"/></el-form-item><el-form-item label="委托单位"><el-input v-model="form.customerName"/></el-form-item><el-form-item label="报告模板"><el-select v-model="form.templateId" style="width:100%"><el-option v-for="t in templates" :key="t.id" :label="`${t.name} ${t.versionNo}`" :value="t.id"/></el-select></el-form-item><el-form-item label="报告标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="检测结论"><el-input v-model="form.content" type="textarea" :rows="8"/></el-form-item></el-form><template #footer><el-button @click="reportVisible=false">取消</el-button><el-button type="primary" @click="saveReport">保存草稿</el-button></template></el-dialog>
    <el-dialog v-model="templateVisible" :title="templateEditingId?'修改报告模板':'新建报告模板'" width="650px"><el-form label-width="90px"><el-form-item label="模板编码"><el-input v-model="template.code"/></el-form-item><el-form-item label="模板名称"><el-input v-model="template.name"/></el-form-item><el-form-item label="报告类型"><el-input v-model="template.reportType"/></el-form-item><el-form-item label="版本"><el-input v-model="template.versionNo"/></el-form-item><el-form-item label="状态"><el-select v-model="template.status" style="width:100%"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item><el-form-item label="模板内容"><el-input v-model="template.templateContent" type="textarea" :rows="9"/><small v-pre>支持 {{reportNo}}、{{customerName}}、{{content}} 占位符</small></el-form-item></el-form><template #footer><el-button @click="templateVisible=false">取消</el-button><el-button type="primary" @click="saveTemplate">保存模板</el-button></template></el-dialog>
    <el-dialog v-model="previewVisible" title="报告预览" width="760px">
      <div class="preview-toolbar"><el-button class="preview-tool choose-template-tool" @click="choosePreviewTemplate">选择模板</el-button><span class="selected-template">当前模板：{{previewTemplateName||'未选择'}}</span><el-button class="preview-tool print-report-tool" :disabled="!previewTemplateId" @click="printReport">打印</el-button><el-button class="preview-tool export-report-tool" :disabled="!previewTemplateId" @click="openReportExport">导出</el-button></div>
      <el-alert v-if="!previewTemplateId" title="当前报告未选择模板，选择模板后才可导出和打印" type="warning" :closable="false" show-icon/>
      <pre class="report-preview">{{previewContent}}</pre>
    </el-dialog>
    <el-dialog v-model="templatePickerVisible" title="选择报告模板" width="500px" append-to-body><el-form label-width="90px"><el-form-item label="模板"><el-select v-model="pendingTemplateId" clearable placeholder="请选择模板" style="width:100%"><el-option v-for="t in templates.filter(item=>item.status==='ENABLED')" :key="t.id" :label="`${t.name} ${t.versionNo}`" :value="t.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="templatePickerVisible=false">取消</el-button><el-button type="primary" @click="confirmPreviewTemplate">确认选择</el-button></template></el-dialog>
    <el-dialog v-model="exportReportVisible" title="导出报告" width="460px" append-to-body><el-radio-group v-model="exportReportFormat" class="export-format-group"><el-radio-button value="word">Word</el-radio-button><el-radio-button value="excel">Excel</el-radio-button><el-radio-button value="pdf">PDF</el-radio-button></el-radio-group><template #footer><el-button @click="exportReportVisible=false">取消</el-button><el-button type="primary" @click="confirmReportExport">确认导出</el-button></template></el-dialog>
  </section>
</template>

<style scoped>
.report-action-bar{display:flex;align-items:center;gap:8px;margin-bottom:12px}.primary-entry,.import-template-button{height:38px;min-width:110px;font-size:14px;font-weight:800}.import-template-button{display:inline-flex;align-items:center;justify-content:center;border-radius:8px;background:linear-gradient(110deg,#0fa36f,#25bd8a);color:#fff;cursor:pointer}.import-template-button input{display:none}.report-row-actions{display:flex;align-items:center;gap:5px}.report-row-actions :deep(.el-button+.el-button){margin-left:0}.template-delete-wrapper{display:inline-flex}.row-action{height:38px;min-width:76px;border:0;border-radius:8px;color:#fff;font-size:14px;font-weight:800}.edit-template-action,.submit-report-action{background:linear-gradient(110deg,#168bea,#396afc)}.export-template-action{background:linear-gradient(110deg,#6b70e8,#5546c7)}.delete-template-action,.reject-report-action{background:linear-gradient(110deg,#f05c68,#d9364e)}.delete-template-action.is-disabled{background:#c5c9d1!important;border-color:#c5c9d1!important;color:#fff!important}.preview-report-action{background:linear-gradient(110deg,#6b70e8,#5546c7)}.print-row-action{background:linear-gradient(110deg,#f2a52b,#e67b18)}.export-row-action{background:linear-gradient(110deg,#0fa36f,#25bd8a)}.print-row-action.is-disabled,.export-row-action.is-disabled{background:#c5c9d1!important;color:#fff!important}.approve-report-action{min-width:96px;background:linear-gradient(110deg,#0fa36f,#25bd8a)}.distribute-report-action{background:linear-gradient(110deg,#f2a52b,#e67b18)}.archive-report-action{background:linear-gradient(110deg,#68758c,#455166)}.preview-toolbar{display:flex;align-items:center;gap:10px;margin-bottom:14px}.selected-template{flex:1;color:#667085;font-size:13px}.preview-tool{height:38px;border:0;border-radius:8px;color:#fff;font-weight:800}.choose-template-tool{background:linear-gradient(110deg,#168bea,#396afc)}.export-report-tool{background:linear-gradient(110deg,#0fa36f,#25bd8a)}.print-report-tool{background:linear-gradient(110deg,#f2a52b,#e67b18)}.preview-tool.is-disabled{background:#c5c9d1!important;color:#fff!important}.report-preview{white-space:pre-wrap;line-height:1.9;padding:24px;background:#f7f9fc;border-radius:12px}.export-format-group{display:flex;justify-content:center;width:100%}.export-format-group :deep(.el-radio-button__inner){min-width:110px;padding:14px 24px;font-weight:800}
</style>
